//
//  SampleData.swift
//  OpenParliament
//
//  Namespace for the bundled dataset. The records themselves live in the
//  neighbouring `SampleMPs`, `SampleBills`, `SampleSchemes` and
//  `SampleSpeeches` files. They serve three purposes:
//
//  • SwiftUI previews, via `ParliamentStore.preview`;
//  • the offline fallback when the server can't be reached;
//  • the source of the server's `db/seed.sql`, generated by
//    `Server/tools/generate-seed.sh`, so both stay identical.
//
//  The joins and aggregates over these records live in `ParliamentStore`.
//
//  Members, parties, constituencies, bills and schemes throughout are
//  illustrative and do not describe any real person, party or audit report.
//

import Foundation

enum SampleData {}
